/**
 * Filesystem route generation (REQ-1, REQ-2): the plugin's half of `research/routing-report.md`.
 *
 * The convention engine lives in `@flamme/router` (`planRoutes`, `emitRoutesModule`); this module is
 * the driver that gives it a project: which files exist under the pages directory, which documents
 * the compiler extracted, which artifacts it compiled, and where the generated tree is written.
 *
 * Two files are produced, and both are only rewritten when their content changed:
 *
 * - `<runtimeDir>/routes.ts` — the route table (`spec`-shaped records with their loaders), the page
 *   metadata map and the typed page registry. Apps import it through `$flamme/routes`.
 * - `<runtimeDir>/auto-routes.ts` — the shim `@flamme/router/auto` imports to install that table
 *   into `createFlammeRouter()`. It is what keeps the router package free of a build-time import of
 *   a file that does not exist until codegen has run.
 */

import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';

import { toPosix, walkFiles, type Diagnostic, type ResolvedConfig } from '@flamme/core';
import {
  RECORDS_DIRECTORY,
  emitRoutesModule,
  emitRoutesShim,
  planRoutes,
  resolveRoutingConfig,
  type RecordModule,
  type RouteComposition,
  type RoutePlan,
  type RouteWarning,
} from '@flamme/router/codegen';

/**
 * The banner every generated file starts with. It is the same line
 * `@flamme/core`'s emitter writes; `packages/vite/test/banner.test.ts` fails if
 * the two spellings ever drift apart.
 */
export const GENERATED_BANNER = '/** This file is automatically generated by Flamme. Do not edit. */';

/**
 * Rewrites an emitter's leading `// GENERATED by …` header to the banner,
 * preserving what follows and staying a no-op on content that already carries it.
 */
export function withGeneratedBanner(content: string): string {
  if (content.startsWith(GENERATED_BANNER)) {
    return content;
  }
  const lines = content.split('\n');
  const first = lines[0];
  if (first !== undefined && first.startsWith('// GENERATED by ') && first.endsWith('do not edit.')) {
    lines.shift();
    // a bare `//` continuation line belongs to the header it followed
    if (lines[0] === '//') {
      lines.shift();
    }
  }
  return `${GENERATED_BANNER}\n${lines.join('\n')}`;
}

/** The generated route module, relative to `runtimeDir`. */
export const ROUTES_FILE = 'routes.ts';

/** The generated shim module, relative to `runtimeDir`. */
export const ROUTES_SHIM_FILE = 'auto-routes.ts';

/** What one route generation pass produced. */
export interface RoutesRun {
  /** The plan the generator computed. */
  readonly plan: RoutePlan;
  /** Generated file (relative to `runtimeDir`) -> content. */
  readonly files: ReadonlyMap<string, string>;
  /**
   * Route component (absolute path) -> the record module that types its `usePageQuery()`. The
   * plugin's rewrite uses this map; a component with no loader is absent.
   */
  readonly records: ReadonlyMap<string, RecordModule>;
  /** Findings about the route tree, reported through the plugin's logger. */
  readonly warnings: readonly RouteWarning[];
  /** Extraction diagnostics (`walkFiles` reports unreadable directories through these). */
  readonly diagnostics: readonly Diagnostic[];
}

/** The input of {@link generateRoutes}: everything codegen already knows plus the project's paths. */
export interface GenerateRoutesOptions {
  /** The resolved compiler config (its `routing` member holds the conventions). */
  readonly config: ResolvedConfig;
  /**
   * The documents `extractProject` found, as `{ relativePath, name, kind, raw, ast, surface }`.
   * Passing the compiler's own extraction (rather than rescanning) is what guarantees a route's
   * loader names an artifact that exists.
   */
  readonly documents: readonly RoutesDocument[];
  /** The compiled artifact names. */
  readonly artifacts: readonly string[];
  /**
   * The route composition (`planComposition`), when the project composes. The emitter moves a
   * composing record's own document loaders into `unattachedLoaders` and gives it the composed one.
   */
  readonly composition?: RouteComposition | undefined;
}

/**
 * The document shape `planRoutes` reads. `@flamme/core`'s `RawDocument` satisfies it structurally,
 * so the plugin passes the extraction result through without copying it.
 */
export type RoutesDocument = Parameters<typeof planRoutes>[0]['documents'][number];

/**
 * Reads the pages tree and plans the route table. Pure apart from the directory walk, so a test can
 * point it at a temp project.
 */
export async function generateRoutes(options: GenerateRoutesOptions): Promise<RoutesRun> {
  const { config } = options;
  const routing = resolveRoutingConfig(config);
  const walked = await pageFiles(config, routing.pagesDir);
  const plan = planRoutes({
    config,
    projectDir: toPosix(config.projectDir),
    runtimeDir: toPosix(config.runtimeDir),
    files: walked.files,
    documents: options.documents,
    artifacts: options.artifacts,
  });
  const emitted = emitRoutesModule(plan, options.composition);
  return {
    plan,
    records: emitted.records,
    files: routeModuleFiles(plan, options.composition),
    warnings: plan.warnings,
    diagnostics: walked.diagnostics,
  };
}

/**
 * Every generated route module of one plan, keyed by its path relative to `runtimeDir`: the route
 * table, the shim `@flamme/router/auto` imports, the per-record modules that carry the typed
 * `usePageQuery()` and the barrel over them.
 *
 * Both drivers write this map (`generateRoutes` for the Vite plugin, `flammeRoutesPlugin` for the
 * CLI), so a route component's rewritten `$flamme/records/<record>` import resolves whichever
 * driver generated the tree. The emitters' headers predate the banner convention, so they are
 * normalized here, where the files are written, and every generated file starts with the same line.
 */
export function routeModuleFiles(
  plan: RoutePlan,
  composition?: RouteComposition,
): ReadonlyMap<string, string> {
  const emitted = emitRoutesModule(plan, composition);
  return new Map<string, string>([
    [ROUTES_FILE, withGeneratedBanner(emitted.code)],
    [ROUTES_SHIM_FILE, withGeneratedBanner(emitRoutesShim())],
    ...[...emitted.files].map(
      ([file, content]): [string, string] => [file, withGeneratedBanner(content)],
    ),
  ]);
}

/** The pages tree, as absolute posix path -> source, plus the walk's diagnostics. */
async function pageFiles(
  config: ResolvedConfig,
  pagesDir: string,
): Promise<{ readonly files: Record<string, string>; readonly diagnostics: readonly Diagnostic[] }> {
  const diagnostics: Diagnostic[] = [];
  const discovered = await walkFiles(
    config.projectDir,
    // The pages directory is a convention, not a second `include`: a project whose `include` does
    // not cover `src/pages` simply plans no routes, which the warnings below make visible.
    [pagesDir === '' ? '**/*' : `${pagesDir}/**/*`],
    config.exclude,
    diagnostics,
    'flamme.config.ts',
  );
  const entries = await Promise.all(
    discovered.map(async (entry): Promise<readonly [string, string] | undefined> => {
      const source = await readFile(entry.absolute, 'utf8').catch(() => undefined);
      return source === undefined ? undefined : [toPosix(entry.absolute), source];
    }),
  );
  const files: Record<string, string> = {};
  for (const entry of entries) {
    if (entry !== undefined) {
      files[entry[0]] = entry[1];
    }
  }
  return { files, diagnostics };
}

/**
 * `true` when the generated route modules on disk already carry this run's content, so a caller can
 * skip writing (and a hot path can skip planning altogether).
 */
export async function routesAreCurrent(run: RoutesRun, runtimeDir: string): Promise<boolean> {
  const current = await Promise.all(
    [...run.files].map(async ([file, content]): Promise<boolean> => {
      const existing = await readFile(join(runtimeDir, file), 'utf8').catch(() => undefined);
      return existing === content;
    }),
  );
  return current.every(Boolean);
}

/**
 * Writes the generated route modules, skipping the files whose content is unchanged, and deletes
 * the record modules the plan no longer names.
 */
export async function writeRoutes(run: RoutesRun, runtimeDir: string): Promise<readonly string[]> {
  const outcomes = await Promise.all(
    [...run.files].map(async ([file, content]): Promise<string | undefined> => {
      const target = join(runtimeDir, file);
      const existing = await readFile(target, 'utf8').catch(() => undefined);
      if (existing === content) {
        return undefined;
      }
      await mkdir(dirname(target), { recursive: true });
      await writeFile(target, content, 'utf8');
      return file;
    }),
  );
  await removeStaleRecordModules(run.files, runtimeDir);
  return outcomes.filter((file): file is string => file !== undefined);
}

/**
 * Deletes the record modules an earlier run left behind, the way `removeStaleArtifacts` prunes
 * `artifacts/`.
 *
 * `records/` is the writer's own directory: its modules are named after the records the plan
 * declares, so a file this run did not emit is stale by construction. Without the sweep a deleted
 * or renamed route left `records/<old>.ts` behind, importing an artifact the same run had swept,
 * and the tree stopped type-checking (`TS2307: Cannot find module '../artifacts/Other'`). The route
 * table, the shim and the barrel always carry their fixed names, so only the record directory can
 * hold a stale file.
 */
async function removeStaleRecordModules(
  files: ReadonlyMap<string, string>,
  runtimeDir: string,
): Promise<void> {
  const prefix = `${RECORDS_DIRECTORY}/`;
  const keep = new Set<string>();
  for (const file of files.keys()) {
    if (file.startsWith(prefix)) {
      keep.add(file.slice(prefix.length));
    }
  }
  const directory = join(runtimeDir, RECORDS_DIRECTORY);
  const entries = await readdir(directory).catch(() => [] as string[]);
  const stale = entries.filter((entry) => entry.endsWith('.ts') && !keep.has(entry));
  await Promise.all(stale.map((entry) => rm(join(directory, entry), { force: true })));
}
